<template><section class="rps"><header><button @click="$router.push('/personal/games')">← 游戏大厅</button><h1>石头剪刀布</h1><button @click="reset">重开</button></header><div class="score"><b>你 {{ mine }}</b><span>VS</span><b>{{ cpu }} 电脑</b></div><div class="battle"><span>{{ myIcon }}</span><em>{{ result }}</em><span>{{ cpuIcon }}</span></div><div class="choices"><button v-for="(x,i) in icons" :key="x" @click="play(i)">{{ x }}</button></div><p>五局三胜，先得到 3 分获胜</p></section></template>
<script setup lang="ts">import{ref}from'vue';const icons=['✊','✌️','✋'],mine=ref(0),cpu=ref(0),myIcon=ref('❔'),cpuIcon=ref('❔'),result=ref('请选择');function play(i:number){if(mine.value===3||cpu.value===3)return;const c=~~(Math.random()*3);myIcon.value=icons[i];cpuIcon.value=icons[c];if(i===c)result.value='平局';else if((i===0&&c===1)||(i===1&&c===2)||(i===2&&c===0)){mine.value++;result.value='你赢了！'}else{cpu.value++;result.value='电脑获胜'}if(mine.value===3)result.value='🎉 你赢得比赛！';if(cpu.value===3)result.value='电脑赢得比赛'}function reset(){mine.value=cpu.value=0;myIcon.value=cpuIcon.value='❔';result.value='请选择'}</script>
<style scoped>.rps{max-width:600px;margin:auto;text-align:center;padding:15px}.rps header{display:flex;justify-content:space-between;align-items:center}.rps button{border:1px solid var(--c-border);background:var(--c-bg-card);color:var(--c-text-2);border-radius:10px;padding:10px}.score{display:flex;justify-content:center;gap:35px;margin:40px;font-size:22px;color:var(--c-purple)}.battle{display:flex;align-items:center;justify-content:center;gap:45px}.battle span{font-size:85px}.battle em{font-style:normal;color:var(--c-cyan);font-weight:700}.choices{display:flex;justify-content:center;gap:15px;margin:40px}.choices button{font-size:43px;padding:15px}.rps p{color:var(--c-text-3)}@media(max-width:500px){.battle{gap:15px}.battle span{font-size:60px}.rps header{flex-wrap:wrap}.rps h1{order:3;width:100%}}</style>
